+  "activeMessagePosition",
+] as const;
+function objectRecord(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null;
+}
+/** Opaque binding only; never include this token in logs. No runtime config dependency. */
+export function sourceToken(anchor: unknown): string | undefined {
+  try {
+    if (
+      !objectRecord(anchor) ||
+      !["agentId", "sessionId", "sessionKey", "storePath", "entryId", "generation"].every(
+        (key) => typeof anchor[key] === "string",
+      ) ||
+      !["rawSeq", "activeMessagePosition"].every(
+        (key) =>
+          typeof anchor[key] === "number" && Number.isSafeInteger(anchor[key]) && anchor[key] >= 0,
+      ) ||
+      !(anchor.effectiveParentId === null || typeof anchor.effectiveParentId === "string")
+    ) {
+      return undefined;
+    }
+    return createHash("sha256")
+      .update(JSON.stringify(keys.map((key) => anchor[key])))
+      .digest("hex");
+  } catch {
+    return undefined;
+  }
+}
+function validated(value: unknown): ContextDiagnostic | undefined {
+  try {
+    if (
+      !objectRecord(value) ||
+      Object.getPrototypeOf(value) !== Object.prototype ||
+      Object.keys(value).toSorted().join(",") !== "reason,sourceToken,stage,version"
+    ) {
+      return undefined;
+    }
+    // Inspect descriptors before reading fields; diagnostic accessors are never invoked.
+    if (
+      Object.values(Object.getOwnPropertyDescriptors(value)).some((d) => !Object.hasOwn(d, "value"))
+    ) {
+      return undefined;
+    }
+    if (
+      value.version !== 1 ||
+      typeof value.reason !== "string" ||
+      !reasons.has(value.reason) ||
+      typeof value.stage !== "string" ||
+      !stages.has(value.stage) ||
+      typeof value.sourceToken !== "string" ||
+      !/^[a-f0-9]{64}$/.test(value.sourceToken)
+    ) {
+      return undefined;
+    }
+    return Object.freeze({
+      version: 1,
+      // SAFETY: The exact reason whitelist was checked above before this immutable copy.
+      reason: value.reason as ContextDiagnosticReason,
+      // SAFETY: The exact stage whitelist was checked above before this immutable copy.
+      stage: value.stage as ContextDiagnosticStage,
+      sourceToken: value.sourceToken,
+    });
+  } catch {
+    return undefined;
+  }
+}
+export function annotateContextFailure<T>(
+  error: T,
+  anchor: unknown,
+  reason: ContextDiagnosticReason,
+  stage: ContextDiagnosticStage,
+): T {
+  try {
+    const value = validated({ version: 1, reason, stage, sourceToken: sourceToken(anchor) });
+    if (value && objectRecord(error)) {
+      details.set(error, value);
+    }
+  } catch {
+    /* Diagnostics must not change the refusal. */
+  }
+  return error;
+}
+export function serializeContextDiagnostic(error: unknown): ContextDiagnostic | undefined {
+  return objectRecord(error) ? details.get(error) : undefined;
+}
+export function decodeContextDiagnostic<T extends Error & { code: string }>(
+  error: T,
+  value: unknown,
+  expectedToken?: string,
+): T {
+  try {
+    const detail = validated(value);
+    if (
+      error.message === "Completed-turn transcript anchor changed" &&
+      error.code === "failed" &&
+      typeof expectedToken === "string" &&
+      detail?.sourceToken === expectedToken
+    ) {
+      details.set(error, detail);
+    }
+  } catch {
+    /* Diagnostics must not change the refusal. */
+  }
+  return error;
+}
+export function readContextDiagnostic(
+  error: unknown,
+  anchor: unknown,
+): ContextDiagnostic | undefined {
+  try {
+    const detail = objectRecord(error) ? details.get(error) : undefined;
+    return detail && detail.sourceToken === sourceToken(anchor) ? detail : undefined;
+  } catch {
+    return undefined;
+  }
+}
+export function recordContextDiagnostic(
+  error: unknown,
+  anchor: unknown,
+  phase: ContextDiagnosticPhase,
+  write: (detail: LogDiagnostic) => void,
+): void {
+  try {
+    const detail = readContextDiagnostic(error, anchor);
+    if (detail && phases.has(phase)) {
+      write({ version: detail.version, reason: detail.reason, stage: detail.stage, phase });
+    }
+  } catch {
+    /* A logging failure must never replace the original refusal. */
+  }
+}
