import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { execFileSync } from "node:child_process";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import type { OpenClawConfig } from "openclaw/plugin-sdk/config-contracts";
import { createTestPluginApi } from "openclaw/plugin-sdk/plugin-test-api";
import plugin from "./extensions/comfy/index.ts";

const PREVIOUS_WORKFLOW_FILE_MAX_BYTES = 16 * 1024 * 1024;
const DEFAULT_COMFY_WORKFLOW_FILE_MAX_BYTES = 100 * 1024 * 1024;

function writeJson(response: ServerResponse, body: unknown): void {
  response.statusCode = 200;
  response.setHeader("content-type", "application/json");
  response.end(JSON.stringify(body));
}

async function readRequestBody(request: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  }
  return Buffer.concat(chunks).toString("utf8");
}

async function main(): Promise<void> {
  console.log(`head: ${execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim()}`);
  const tempRoot = await fs.mkdtemp(path.join(os.tmpdir(), "openclaw-comfy-workflow-proof-"));
  let requestCount = 0;
  let submittedWorkflow: Record<string, unknown> | undefined;
  const promptId = "exact-head-proof-prompt";
  const server = createServer(async (request, response) => {
    requestCount += 1;
    const requestUrl = new URL(request.url ?? "/", "http://127.0.0.1");
    if (request.method === "POST" && requestUrl.pathname === "/prompt") {
      const payload = JSON.parse(await readRequestBody(request)) as { prompt?: unknown };
      submittedWorkflow = payload.prompt as Record<string, unknown> | undefined;
      writeJson(response, { prompt_id: promptId });
      return;
    }
    if (request.method === "GET" && requestUrl.pathname === `/history/${promptId}`) {
      writeJson(response, {
        [promptId]: {
          outputs: {
            "9": {
              images: [{ filename: "proof.png", subfolder: "", type: "output" }],
            },
          },
        },
      });
      return;
    }
    if (request.method === "GET" && requestUrl.pathname === "/view") {
      response.statusCode = 200;
      response.setHeader("content-type", "image/png");
      response.end(Buffer.from("proof-png"));
      return;
    }
    response.statusCode = 404;
    response.end("not found");
  });

  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });

  try {
    const address = server.address();
    if (!address || typeof address === "string") {
      throw new Error("localhost proof server did not expose a TCP address");
    }
    const baseUrl = `http://127.0.0.1:${address.port}`;
    const workflow = JSON.stringify({
      "6": { class_type: "CLIPTextEncode", inputs: { text: "" } },
      "9": { class_type: "SaveImage", inputs: {} },
    });
    const targetPath = path.join(tempRoot, "workflow-target.json");
    const symlinkPath = path.join(tempRoot, "workflow-link.json");
    await fs.writeFile(targetPath, workflow, "utf8");
    await fs.symlink(targetPath, symlinkPath);

    const configFor = (workflowPath: string, workflowFileMaxBytes?: number) =>
      ({
        plugins: {
          entries: {
            comfy: {
              config: {
                baseUrl,
                ...(workflowFileMaxBytes === undefined ? {} : { workflowFileMaxBytes }),
                image: {
                  workflowPath,
                  promptNodeId: "6",
                  outputNodeId: "9",
                },
              },
            },
          },
        },
      }) as unknown as OpenClawConfig;

    const imageProviders: Array<{ id: string; generateImage: (request: never) => Promise<any> }> = [];
    plugin.register(
      createTestPluginApi({
        config: {} as never,
        registerImageGenerationProvider(provider) {
          imageProviders.push(provider as never);
        },
      }),
    );
    const provider = imageProviders.find((candidate) => candidate.id === "comfy");
    if (!provider) {
      throw new Error("Comfy image generation provider was not registered");
    }
    const defaultResult = await provider.generateImage({
      provider: "comfy",
      model: "workflow",
      prompt: "exact-head default workflow",
      cfg: configFor(symlinkPath),
    });
    const defaultLinkPreserved = (await fs.lstat(symlinkPath)).isSymbolicLink();
    const defaultWorkflowLoaded = submittedWorkflow?.["6"] !== undefined;
    const defaultSucceeded =
      defaultLinkPreserved &&
      defaultResult.metadata?.promptId === promptId &&
      defaultResult.images.length === 1 &&
      defaultWorkflowLoaded;
    console.log(
      `default-provider: cap=none linkPreserved=${defaultLinkPreserved} promptId=${defaultResult.metadata?.promptId} images=${defaultResult.images.length} workflowLoaded=${defaultWorkflowLoaded}`,
    );
    if (!defaultSucceeded) {
      throw new Error("default workflow provider path or symlink preservation proof failed");
    }
    const symlinkResult = await provider.generateImage({
      provider: "comfy",
      model: "workflow",
      prompt: "exact-head symlink workflow",
      cfg: configFor(symlinkPath, Buffer.byteLength(workflow)),
    });
    const symlinkLinkPreserved = (await fs.lstat(symlinkPath)).isSymbolicLink();
    const symlinkSucceeded =
      symlinkLinkPreserved &&
      symlinkResult.metadata?.promptId === promptId &&
      symlinkResult.images.length === 1 &&
      submittedWorkflow?.["6"] !== undefined;
    console.log(
      `symlink-real-chain: linkPreserved=${symlinkLinkPreserved} promptId=${symlinkResult.metadata?.promptId} images=${symlinkResult.images.length} workflowLoaded=${submittedWorkflow?.["6"] !== undefined}`,
    );
    if (!symlinkSucceeded) {
      throw new Error("symlink workflow did not traverse submit, history, and image download");
    }

    const largeWorkflow = JSON.stringify({
      "6": {
        class_type: "CLIPTextEncode",
        inputs: { text: "" },
        _meta: { title: "x".repeat(PREVIOUS_WORKFLOW_FILE_MAX_BYTES) },
      },
      "9": { class_type: "SaveImage", inputs: {} },
    });
    const largePath = path.join(tempRoot, "large-workflow.json");
    await fs.writeFile(largePath, largeWorkflow, "utf8");
    const largeResult = await provider.generateImage({
      provider: "comfy",
      model: "workflow",
      prompt: "exact-head large workflow",
      cfg: configFor(largePath, DEFAULT_COMFY_WORKFLOW_FILE_MAX_BYTES),
    });
    const largeByteLength = Buffer.byteLength(largeWorkflow);
    const largeSucceeded =
      largeByteLength > PREVIOUS_WORKFLOW_FILE_MAX_BYTES &&
      largeResult.metadata?.promptId === promptId &&
      largeResult.images.length === 1 &&
      submittedWorkflow?.["6"] !== undefined;
    console.log(
      `large-configured: bytes=${largeByteLength} abovePrevious=${largeByteLength > PREVIOUS_WORKFLOW_FILE_MAX_BYTES} images=${largeResult.images.length}`,
    );
    if (!largeSucceeded) {
      throw new Error("large workflow did not traverse configured reader and provider calls");
    }

    const oversizedPath = path.join(tempRoot, "oversized-workflow.json");
    await fs.writeFile(oversizedPath, "", "utf8");
    await fs.truncate(oversizedPath, DEFAULT_COMFY_WORKFLOW_FILE_MAX_BYTES + 1);
    const requestsBeforeCap = requestCount;
    let capRejected = false;
    let actionable = false;
    try {
      await provider.generateImage({
        provider: "comfy",
        model: "workflow",
        prompt: "must be rejected before the local service",
        cfg: configFor(oversizedPath, DEFAULT_COMFY_WORKFLOW_FILE_MAX_BYTES),
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      capRejected = message.includes(`exceeds ${DEFAULT_COMFY_WORKFLOW_FILE_MAX_BYTES} bytes`);
      actionable = message.includes("workflowFileMaxBytes");
    }
    console.log(
      `negative-control: configured-cap-rejected=${capRejected} actionable=${actionable} requestCountUnchanged=${requestCount === requestsBeforeCap}`,
    );
    if (!capRejected || !actionable || requestCount !== requestsBeforeCap) {
      process.exitCode = 1;
    } else {
      console.log(`proof-complete: productionRequests=${requestCount} oversizeRequestRejectedBeforeHttp=true`);
    }
  } finally {
    await new Promise<void>((resolve, reject) => {
      server.close((error) => (error ? reject(error) : resolve()));
    });
    await fs.rm(tempRoot, { recursive: true, force: true });
  }
}

void main();
```

