const { acquireGatewayE2ePortBlock, startClaimedGateway } =
  await import("./src/gateway/test-helpers.listener.js");
const { connectGatewayClient, disconnectGatewayClient } =
  await import("./src/gateway/test-helpers.e2e.js");

const { prepareSystemAgentRunAdmission } = await import("./src/agents/admitted-run-context.js");

let oldLease: Awaited<ReturnType<typeof acquirePreparedModelRuntimeSnapshot>> | undefined;
let gateway: Awaited<ReturnType<typeof startGatewayServer>> | undefined;
let client: Awaited<ReturnType<typeof connectGatewayClient>> | undefined;
let blocker: Promise<void> | undefined;
let queued: Promise<unknown> | undefined;
const release = createDeferredCore<void>();
const summary: Record<string, unknown> = {
  head: execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim(),
  runtime: process.version,
  configValidated: true,
  ownerSha256: createHash("sha256")
    .update(await fs.readFile("src/gateway/server-methods/system-agent-execution.ts"))
    .digest("hex"),
  driverSha256: createHash("sha256")
    .update(await fs.readFile("proof-row14-system-queue.mts"))
    .digest("hex"),
  trackedSourceClean:
    execFileSync("git", ["diff", "--name-only"], { encoding: "utf8" }).trim() === "",
  scope: "independent system-agent queue hardening; not normal-delegation outage",
};
try {
  await fs.writeFile(process.env.OPENCLAW_CONFIG_PATH!, JSON.stringify(initialConfig));
  const claim = await acquireGatewayE2ePortBlock();
  gateway = await startClaimedGateway(claim, () =>
    startGatewayServer(claim.port, {
      bind: "loopback",
      controlUiEnabled: false,
      auth: { mode: "token", token: "<synthetic-token-redacted>" },
    }),
  );
  await gateway.startupSettled;
  client = await connectGatewayClient({
    url: `ws://<loopback>:${claim.port}`,
    token: "<synthetic-token-redacted>",
    scopes: ["operator.admin"],
  });
  const health = await client.request<{ ok: boolean; plugins: { loaded: string[] } }>("health", {});
  assert.equal(health.ok, true);
  assert.deepEqual(health.plugins.loaded, ["openai"]);
  summary.gatewayAuthenticated = true;
  summary.loadedPlugins = health.plugins.loaded;
  await fs.writeFile(
    path.join(artifacts, "checkpoint.json"),
    JSON.stringify(summary, null, 2) + "\n",
  );
  const oldConfig = getRuntimeConfigSnapshot();
  assert(oldConfig, "Gateway must own the active validated config");
  const currentConfig: OpenClawConfig = structuredClone(oldConfig);
  currentConfig.agents!.defaults!.models!["row14-proof/row14-model"] = {
    alias: "current-admitted-alias",
  };
  oldLease = await acquirePreparedModelRuntimeSnapshot({
    config: oldConfig,
    agentId: "main",
    agentDir,
    workspaceDir,
  });
  const generation = oldLease.pluginGeneration;
  summary.parentLeaseAcquired = true;
  await fs.writeFile(
    path.join(artifacts, "checkpoint.json"),
    JSON.stringify(summary, null, 2) + "\n",
  );
  const started = createDeferredCore<void>();
  blocker = runSystemAgentGatewayTask(async () => {
    started.resolve();
    await release.promise;
  });
  await started.promise;
  const controller = new AbortController();
  const caller = {
    agentId: "main",
    sessionKey: "agent:main:row14-parent",
    approvalSignals: [controller.signal],
    approvalAuthorityCheck: () => !controller.signal.aborted,
  };
  queued = withGatewayToolCallerIdentity(caller, () =>
    withPreparedModelRuntimePluginGenerationScope(
      generation,
      () =>
        withPluginRuntimeGenerationScope(
          {
            metadataSnapshot: generation.pluginMetadataSnapshot,
            pluginRegistry: generation.pluginRegistry,
          },
          async () => {
            try {
              return await runSystemAgentGatewayTask(async () => {
                summary.inheritedParentGeneration =
                  getPreparedModelRuntimePluginGeneration() === generation;
                summary.callerPreserved =
                  getGatewayToolCallerIdentity()?.sessionKey === caller.sessionKey &&
                  getGatewayToolCallerIdentity()?.approvalSignals?.[0] === controller.signal &&
                  getGatewayToolCallerIdentity()?.approvalAuthorityCheck?.() === true;
                const admission = prepareSystemAgentRunAdmission(
                  currentConfig,
                  "row14-queued-real-runtime",
                  "main",
                  "system-agent.turn",
                  () => {
                    assert(
                      caller.approvalAuthorityCheck(),
                      "original caller authority must remain current",
                    );
                  },
                );
                try {
                  return await runEmbeddedAgent({
                    preparedRunAdmission: admission,
                    sessionId: "row14-isolated-task",
                    sessionKey: "agent:main:row14-task",
                    agentId: "main",
                    agentDir,
                    workspaceDir,
                    sessionPersistence: "detached",
                    config: currentConfig,
                    provider: "row14-proof",
                    model: "row14-model",
                    prompt: "Reply exactly ROW14_CURRENT_TASK_DONE.",
                    toolsAllow: [],
                    timeoutMs: 60000,
                    runId: "row14-queued-real-runtime",
                  });
                } finally {
                  admission.close();
                }
              });
            } finally {
              summary.parentGenerationRestored =
                getPreparedModelRuntimePluginGeneration() === generation;
            }
          },
        ),
      () => oldLease?.snapshot,
    ),
  );
  // Replacement happens after enqueue, while the independent task waits at the real lock.
  await fs.writeFile(process.env.OPENCLAW_CONFIG_PATH!, JSON.stringify(currentConfig));
  setRuntimeConfigSnapshot(currentConfig, currentConfig);
  summary.replacementStarted = true;
  await fs.writeFile(
    path.join(artifacts, "checkpoint.json"),
    JSON.stringify(summary, null, 2) + "\n",
  );
  await refreshPreparedModelRuntimeSnapshots(currentConfig, {
    gatewayLifecycle: true,
    catalogMode: "static",
  });
  summary.replacementPublished = true;
  await fs.writeFile(
    path.join(artifacts, "checkpoint.json"),
    JSON.stringify(summary, null, 2) + "\n",
  );
  release.resolve();
  await blocker;
  const result = await queued;
  summary.completed = JSON.stringify(result).includes("ROW14_CURRENT_TASK_DONE");
} catch (error) {
  summary.error = error instanceof Error ? error.message : String(error);
} finally {
  summary.providerRequests = captures.length;
  const systemPrompts = captures.map((body) =>
    body.messages
      .filter((message) => message.role === "system" || message.role === "developer")
      .map((message) => JSON.stringify(message.content))
      .join("\n"),
  );
  summary.currentAliasPresent =
    systemPrompts.length > 0 &&
    systemPrompts.every((prompt) => prompt.includes("current-admitted-alias"));
  summary.oldAliasAbsent = systemPrompts.every((prompt) => !prompt.includes("old-admitted-alias"));
  release.resolve();
  await Promise.allSettled([blocker, queued]);
  await oldLease?.[Symbol.asyncDispose]();
  if (client) await disconnectGatewayClient(client);
  if (gateway) await gateway.close({ reason: "row14 isolated proof complete" });
  await closePreparedModelRuntimeSnapshots();
  clearRuntimeConfigSnapshot();
  await closeNativeProvider(provider);
  await fs.writeFile(path.join(artifacts, "summary.json"), JSON.stringify(summary, null, 2) + "\n");
}
assert.equal(
  summary.gatewayAuthenticated,
  true,
  "real isolated Gateway must start and authenticate a client",
);
assert.equal(summary.replacementPublished, true, "replacement must publish before queue release");
assert.equal(summary.callerPreserved, true, "caller authority must survive generation isolation");
assert.equal(
  summary.inheritedParentGeneration,
  false,
  "independent task must not inherit parent generation",
);
assert.equal(summary.parentGenerationRestored, true, "parent admitted scope must resume");
assert.equal(
  summary.currentAliasPresent,
  true,
  "actual model request must contain replacement alias metadata",
);
assert.equal(
  summary.oldAliasAbsent,
  true,
  "actual model request must not contain parent alias metadata",
);
assert.equal(summary.completed, true, "real embedded model HTTP turn must finish");
console.log(JSON.stringify(summary));
```

